import { FreshnessContractViolation } from './freshness.js';
import { decideTransaction, embeddedResult, EmbeddedTransactionRejected, } from './embedded-transaction.js';
/** Durable browser runtime. Every mutation resolves only after its IndexedDB transaction commits. */
export class IndexedDbJsDb {
    database;
    channel;
    sequence = 0;
    origin;
    peers = new Set();
    changeListeners = new Map();
    changeCursor = 0;
    changePollGeneration = 0;
    changePollRunning = false;
    changePollTimer;
    changeChannelListening = false;
    changeCoordinatorReady = false;
    pendingChangeAnnouncements = [];
    announcedChangeSequences = new Set();
    constructor(namespace) {
        if (typeof indexedDB === 'undefined')
            throw new Error('IndexedDB is unavailable in this browser');
        this.database = this.open(`feltdb:${namespace}`);
        this.origin = `browser:${namespace}`;
        if (typeof BroadcastChannel !== 'undefined')
            this.channel = new BroadcastChannel(`feltdb:${namespace}:changes`);
    }
    open(name) {
        return new Promise((resolve, reject) => {
            const request = indexedDB.open(name, 2);
            request.onupgradeneeded = () => {
                const db = request.result;
                if (!db.objectStoreNames.contains('rows'))
                    db.createObjectStore('rows');
                if (!db.objectStoreNames.contains('changes'))
                    db.createObjectStore('changes', { keyPath: 'sequence', autoIncrement: true });
                // Committed transaction ids, so redelivery after a reload is a no-op.
                if (!db.objectStoreNames.contains('transactions'))
                    db.createObjectStore('transactions');
            };
            request.onsuccess = () => resolve(request.result);
            request.onerror = () => reject(request.error ?? new Error('open IndexedDB failed'));
            request.onblocked = () => reject(new Error('IndexedDB upgrade blocked by another tab'));
        });
    }
    splitKey(key) {
        const separator = key.indexOf(':');
        if (separator < 1)
            throw new Error(`Invalid FeltDB key: ${key}`);
        return key.slice(0, separator);
    }
    async mutate(key, value, type) {
        try {
            const db = await this.database;
            let committedSequence = 0;
            const collection = this.splitKey(key);
            await new Promise((resolve, reject) => {
                let transaction;
                try {
                    transaction = db.transaction(['rows', 'changes'], 'readwrite', { durability: 'strict' });
                }
                catch {
                    transaction = db.transaction(['rows', 'changes'], 'readwrite');
                }
                if (type === 'delete')
                    transaction.objectStore('rows').delete(key);
                else
                    transaction.objectStore('rows').put(value, key);
                const changes = transaction.objectStore('changes');
                const timestamp = Date.now();
                const change = changes.add({ collection, key, type, value, timestamp, origin: this.origin, id: `${this.origin}:${timestamp}:${Math.random().toString(36).slice(2)}` });
                change.onsuccess = () => {
                    const sequence = Number(change.result);
                    committedSequence = sequence;
                    if (sequence > 10_000)
                        changes.delete(IDBKeyRange.upperBound(sequence - 10_000));
                };
                transaction.oncomplete = () => resolve();
                transaction.onerror = () => reject(transaction.error ?? new Error('IndexedDB mutation failed'));
                transaction.onabort = () => reject(transaction.error ?? new Error('IndexedDB mutation aborted'));
            });
            this.sequence += 1;
            this.announceLocalChange(collection, committedSequence);
            this.channel?.postMessage({ collection, sequence: committedSequence });
            return { success: true, data: key };
        }
        catch (error) {
            return { success: false, error: String(error) };
        }
    }
    insert(key, value) { return this.mutate(key, JSON.parse(value), 'put'); }
    update(key, value) { return this.mutate(key, JSON.parse(value), 'put'); }
    delete(key) { return this.mutate(key, undefined, 'delete'); }
    /**
     * Commit several operations atomically and durably.
     *
     * Reads, precondition checks, and writes all happen inside a single
     * IndexedDB readwrite transaction, which is the browser's own atomic commit
     * boundary. If any step fails the transaction aborts and nothing is written,
     * and the promise resolves only after the transaction has committed.
     */
    async commit_transaction(request) {
        const db = await this.database;
        const before = this.sequence;
        // A transaction with no operations, or with no identity, would open an
        // IndexedDB transaction that reads nothing and therefore never reaches a
        // decision. Those two are settled first, before a transaction is opened.
        //
        // Nothing else is pre-decided here. Every other question this runtime has
        // to answer -- does the record exist, what version does it hold -- is a
        // question about stored state, and answering it outside the IndexedDB
        // transaction would put another writer between the check and the write.
        if (!request.transactionId?.trim() || request.operations.length === 0) {
            const structural = decideTransaction(request, { exists: () => false, hasApplied: () => false });
            if (structural.kind === 'reject')
                throw new EmbeddedTransactionRejected(structural.reason, structural.failure);
        }
        // Applied transaction ids live in their own store so identity survives a
        // page reload the same way records do.
        const alreadyApplied = await this.request('transactions', store => store.get(request.transactionId));
        if (alreadyApplied !== undefined) {
            return embeddedResult(request, true, before, this.sequence);
        }
        const plan = await new Promise((resolve, reject) => {
            let transaction;
            try {
                transaction = db.transaction(['rows', 'changes', 'transactions'], 'readwrite', { durability: 'strict' });
            }
            catch {
                transaction = db.transaction(['rows', 'changes', 'transactions'], 'readwrite');
            }
            const rows = transaction.objectStore('rows');
            const changes = transaction.objectStore('changes');
            const transactions = transaction.objectStore('transactions');
            // Read every record the transaction touches -- the ones it writes and
            // the ones it only guards -- inside the transaction, so the precondition
            // check and the write cannot be separated by another writer.
            //
            // The values are read, not merely their presence. A `__version`, an
            // authority epoch and a lease all live in the record body, so reading
            // only the key would leave this runtime unable to evaluate the very
            // predicates every other runtime evaluates, and `putIfAbsent` and
            // `updateIfVersion` would mean something weaker in a browser than they
            // mean anywhere else. `get` is no less atomic than `getKey` here: both
            // are issued inside the same readwrite transaction.
            const records = new Map();
            const touched = [...new Set([
                    ...request.operations.map(operation => `${operation.collection}:${operation.id}`),
                    ...(request.preconditions ?? []).map(condition => `${condition.collection}:${condition.id}`),
                ])];
            let pending = touched.length;
            let decided = null;
            const finish = () => {
                const plan = decideTransaction(request, {
                    exists: key => records.get(key) !== undefined,
                    read: key => records.get(key),
                    hasApplied: () => false,
                });
                decided = plan;
                if (plan.kind !== 'apply') {
                    transaction.abort();
                    return;
                }
                const timestamp = Date.now();
                for (const mutation of plan.mutations) {
                    if (mutation.value === undefined)
                        rows.delete(mutation.key);
                    else
                        rows.put(mutation.value, mutation.key);
                    changes.add({
                        collection: mutation.collection,
                        key: mutation.key,
                        type: mutation.value === undefined ? 'delete' : 'put',
                        value: mutation.value,
                        timestamp,
                        origin: this.origin,
                        id: `${this.origin}:${timestamp}:${Math.random().toString(36).slice(2)}`,
                    });
                }
                transactions.put({ transactionId: request.transactionId, committedAt: timestamp }, request.transactionId);
            };
            for (const key of touched) {
                const lookup = rows.get(key);
                lookup.onsuccess = () => {
                    records.set(key, lookup.result);
                    pending -= 1;
                    if (pending === 0)
                        finish();
                };
                lookup.onerror = () => reject(lookup.error ?? new Error('IndexedDB read failed'));
            }
            transaction.oncomplete = () => resolve(decided ?? { kind: 'reject', reason: 'transaction did not decide' });
            transaction.onabort = () => {
                if (decided && decided.kind !== 'apply')
                    resolve(decided);
                else
                    reject(transaction.error ?? new Error('IndexedDB transaction aborted'));
            };
            transaction.onerror = () => {
                if (decided && decided.kind !== 'apply')
                    return;
                reject(transaction.error ?? new Error('IndexedDB transaction failed'));
            };
        });
        if (plan.kind === 'duplicate')
            return embeddedResult(request, true, before, this.sequence);
        if (plan.kind === 'reject')
            throw new EmbeddedTransactionRejected(plan.reason, plan.failure);
        this.sequence += plan.mutations.length;
        for (const mutation of plan.mutations)
            this.announceLocalChange(mutation.collection, this.sequence);
        return embeddedResult(request, false, before, this.sequence);
    }
    async cas(params) {
        try {
            const db = await this.database;
            let result = { updated: false, currentVersion: 0 };
            let committedSequence = 0;
            const collection = this.splitKey(params.key);
            await new Promise((resolve, reject) => {
                let transaction;
                try {
                    transaction = db.transaction(['rows', 'changes'], 'readwrite', { durability: 'strict' });
                }
                catch {
                    transaction = db.transaction(['rows', 'changes'], 'readwrite');
                }
                const rowsStore = transaction.objectStore('rows');
                const changesStore = transaction.objectStore('changes');
                // Read current value inside transaction boundary
                const getRequest = rowsStore.get(params.key);
                getRequest.onsuccess = () => {
                    const existing = getRequest.result;
                    if (existing === undefined) {
                        result = { updated: false, currentVersion: 0 };
                        return;
                    }
                    const existingRecord = existing;
                    const currentVersion = existingRecord.__version ?? 1;
                    // Version check happens inside transaction
                    if (currentVersion !== params.expectedVersion) {
                        result = { updated: false, currentVersion };
                        return;
                    }
                    // Version matches - update it
                    const parsed = JSON.parse(params.value);
                    const newVersion = params.expectedVersion + 1;
                    const updatedRecord = { ...parsed, __version: newVersion };
                    rowsStore.put(updatedRecord, params.key);
                    const timestamp = Date.now();
                    const change = changesStore.add({
                        collection,
                        key: params.key,
                        type: 'put',
                        value: updatedRecord,
                        timestamp,
                        origin: this.origin,
                        id: `${this.origin}:${timestamp}:${Math.random().toString(36).slice(2)}`
                    });
                    change.onsuccess = () => {
                        committedSequence = Number(change.result);
                        result = { updated: true, currentVersion: newVersion };
                    };
                };
                getRequest.onerror = () => {
                    transaction.abort();
                };
                transaction.oncomplete = () => resolve();
                transaction.onerror = () => reject(transaction.error ?? new Error('IndexedDB CAS failed'));
                transaction.onabort = () => reject(transaction.error ?? new Error('IndexedDB CAS aborted'));
            });
            if (result.updated && committedSequence > 0) {
                this.sequence += 1;
                this.announceLocalChange(collection, committedSequence);
                this.channel?.postMessage({ collection, sequence: committedSequence });
            }
            return result;
        }
        catch (error) {
            return { updated: false, currentVersion: 0 };
        }
    }
    async get(key) {
        try {
            const value = await this.request('rows', store => store.get(key));
            return { success: true, data: value === undefined ? undefined : JSON.stringify(value) };
        }
        catch (error) {
            return { success: false, error: String(error) };
        }
    }
    async query(collection) {
        try {
            const db = await this.database;
            const values = await new Promise((resolve, reject) => {
                const request = db.transaction('rows').objectStore('rows').openCursor();
                const output = [];
                request.onsuccess = () => { const cursor = request.result; if (!cursor)
                    return resolve(output); if (String(cursor.key).startsWith(`${collection}:`))
                    output.push(cursor.value); cursor.continue(); };
                request.onerror = () => reject(request.error);
            });
            return { success: true, data: JSON.stringify(values) };
        }
        catch (error) {
            return { success: false, error: String(error) };
        }
    }
    async request(storeName, create) {
        const db = await this.database;
        return new Promise((resolve, reject) => { const request = create(db.transaction(storeName).objectStore(storeName)); request.onsuccess = () => resolve(request.result); request.onerror = () => reject(request.error); });
    }
    subscribe_changes(callback, collection) {
        let listeners = this.changeListeners.get(collection);
        if (!listeners) {
            listeners = new Set();
            this.changeListeners.set(collection, listeners);
        }
        listeners.add(callback);
        if (!this.changePollRunning)
            void this.startChangeCoordinator();
        let subscribed = true;
        return () => {
            if (!subscribed)
                return;
            subscribed = false;
            const current = this.changeListeners.get(collection);
            current?.delete(callback);
            if (current?.size === 0)
                this.changeListeners.delete(collection);
            if (this.changeListeners.size === 0)
                this.stopChangeCoordinator();
        };
    }
    receiveChangeMessage = (event) => {
        if (!event.data?.collection)
            return;
        const announcement = { collection: event.data.collection, sequence: event.data.sequence };
        if (!this.changeCoordinatorReady) {
            this.pendingChangeAnnouncements.push(announcement);
            return;
        }
        this.deliverChangeAnnouncement(announcement);
    };
    deliverChangeAnnouncement(announcement) {
        if (announcement.sequence !== undefined) {
            if (announcement.sequence <= this.changeCursor)
                return;
            if (this.announcedChangeSequences.has(announcement.sequence))
                return;
            this.rememberAnnouncedSequence(announcement.sequence);
        }
        this.notifyChangeListeners(announcement.collection);
    }
    announceLocalChange(collection, sequence) {
        if (this.changeListeners.size === 0)
            return;
        if (sequence)
            this.rememberAnnouncedSequence(sequence);
        this.notifyChangeListeners(collection);
    }
    rememberAnnouncedSequence(sequence) {
        this.announcedChangeSequences.add(sequence);
        // The durable poll normally drains this set within one interval. Bound it
        // defensively if a browser repeatedly delivers announcements while polling fails.
        if (this.announcedChangeSequences.size > 10_000) {
            const oldest = this.announcedChangeSequences.values().next().value;
            if (oldest !== undefined)
                this.announcedChangeSequences.delete(oldest);
        }
    }
    notifyChangeListeners(collection) {
        const listeners = new Set([
            ...(this.changeListeners.get(collection) ?? []),
            ...(this.changeListeners.get(undefined) ?? []),
        ]);
        for (const listener of listeners)
            listener(collection);
    }
    async startChangeCoordinator() {
        if (this.changePollRunning || this.changeListeners.size === 0)
            return;
        this.changePollRunning = true;
        this.changeCoordinatorReady = false;
        const generation = ++this.changePollGeneration;
        if (this.channel && !this.changeChannelListening) {
            this.channel.addEventListener('message', this.receiveChangeMessage);
            this.changeChannelListening = true;
        }
        // A subscription observes future changes; old durable history is audit data,
        // not a queue that every new subscriber must replay.
        try {
            this.changeCursor = await this.latestChangeSequence();
        }
        catch { /* polling retries after initialization failures */ }
        if (generation !== this.changePollGeneration || this.changeListeners.size === 0)
            return;
        for (const sequence of this.announcedChangeSequences) {
            if (sequence <= this.changeCursor)
                this.announcedChangeSequences.delete(sequence);
        }
        this.changeCoordinatorReady = true;
        const pending = this.pendingChangeAnnouncements.splice(0);
        for (const announcement of pending)
            this.deliverChangeAnnouncement(announcement);
        void this.pollChanges(generation);
    }
    async latestChangeSequence() {
        const db = await this.database;
        return new Promise((resolve, reject) => {
            const request = db.transaction('changes').objectStore('changes').openKeyCursor(null, 'prev');
            request.onsuccess = () => resolve(request.result ? Number(request.result.key) : 0);
            request.onerror = () => reject(request.error);
        });
    }
    async pollChanges(generation) {
        if (generation !== this.changePollGeneration || this.changeListeners.size === 0)
            return;
        try {
            const db = await this.database;
            await new Promise((resolve, reject) => {
                const range = this.changeCursor ? IDBKeyRange.lowerBound(this.changeCursor, true) : undefined;
                const request = db.transaction('changes').objectStore('changes').openCursor(range);
                request.onsuccess = () => {
                    const item = request.result;
                    if (!item)
                        return resolve();
                    this.changeCursor = Number(item.key);
                    if (this.announcedChangeSequences.has(this.changeCursor)) {
                        this.announcedChangeSequences.delete(this.changeCursor);
                    }
                    else {
                        this.notifyChangeListeners(item.value.collection);
                    }
                    item.continue();
                };
                request.onerror = () => reject(request.error);
            });
        }
        catch { /* a later poll retries durable events */ }
        if (generation !== this.changePollGeneration || this.changeListeners.size === 0)
            return;
        this.changePollTimer = setTimeout(() => void this.pollChanges(generation), 500);
    }
    stopChangeCoordinator() {
        this.changePollGeneration += 1;
        this.changePollRunning = false;
        this.changeCoordinatorReady = false;
        this.pendingChangeAnnouncements = [];
        if (this.changePollTimer !== undefined)
            clearTimeout(this.changePollTimer);
        this.changePollTimer = undefined;
        this.announcedChangeSequences.clear();
        if (this.channel && this.changeChannelListening) {
            this.channel.removeEventListener('message', this.receiveChangeMessage);
            this.changeChannelListening = false;
        }
    }
    close() {
        this.changeListeners.clear();
        this.stopChangeCoordinator();
        void this.database.then(db => db.close());
        this.channel?.close();
    }
    get_capability_records(capability) { return this.query(capability); }
    execute_op() { return { success: false, error: 'Raw operations are unavailable in IndexedDB' }; }
    sync_info() { return { success: true, data: JSON.stringify({ instance_id: this.origin, sequence: this.sequence, connected_peers: [...this.peers], pending_operations: 0, operations_sent: 0, operations_received: 0, conflicts_detected: 0, last_sync_ms: 0, is_connected: this.peers.size > 0 }) }; }
    add_peer() { return { success: false, error: 'Use a remote runtime for peer sync' }; }
    add_sync_peer(peerId) { this.peers.add(peerId); return { success: true }; }
    remove_sync_peer(peerId) { this.peers.delete(peerId); return { success: true }; }
    get_pending_for_peer() { return { success: true, data: '[]' }; }
    acknowledge_peer_operations() { return { success: true }; }
    instance_id() { return this.origin; }
    get_sequence() { return this.sequence; }
    /**
     * IndexedDB is the serialization authority for this database.
     *
     * The `changes` store is `autoIncrement`, so its key is assigned by the
     * storage engine inside the same readwrite transaction that writes the record,
     * and the browser serializes readwrite transactions on an object store across
     * tabs. A second tab's commit therefore advances the same durable counter,
     * with no coordination code of our own.
     *
     * Note what is *not* used here: `this.sequence` counts what this handle wrote
     * and would miss every other tab. The durable key is the authoritative value.
     */
    freshness() {
        if (this.peers.size > 0) {
            return {
                domain: 'replicated',
                validation: 'refresh',
                invalidation: true,
                reason: 'sync peers order operations causally, so the local autoIncrement key is not authoritative across replicas',
            };
        }
        return {
            domain: 'local-first',
            validation: 'revision',
            invalidation: true,
            revisionScope: this.origin,
        };
    }
    /**
     * The highest durable `changes` key.
     *
     * Read from the store rather than from memory so a write committed by another
     * tab is included. An empty store is revision 0, which is a real value: it
     * means nothing has been committed, and a cache built at 0 is still current.
     */
    async revision() {
        const capability = this.freshness();
        if (capability.validation !== 'revision') {
            throw new FreshnessContractViolation(`browser runtime: ${capability.reason}`);
        }
        const key = await this.request('changes', store => store.openKeyCursor(null, 'prev'));
        const cursor = key;
        return { value: cursor ? Number(cursor.key) : 0, scope: this.origin };
    }
    async audit_events() { return (await this.request('changes', store => store.getAll())).map((value, index) => ({ ...value, sequence: value.sequence ?? index + 1 })); }
    async export_operations(sinceSequence) { return (await this.audit_events()).filter(value => (value.sequence ?? 0) > sinceSequence); }
    async apply_remote_operations(operations) {
        const db = await this.database;
        let applied = 0, ignored = 0;
        for (const operation of operations) {
            const history = await this.audit_events();
            if (history.some(event => event.id === operation.id)) {
                ignored++;
                continue;
            }
            const current = history.filter(event => event.key === operation.key).sort((a, b) => (b.sequence ?? 0) - (a.sequence ?? 0))[0];
            const incomingOrder = `${String(operation.timestamp).padStart(16, '0')}:${operation.origin}:${operation.id}`;
            const currentOrder = current ? `${String(current.timestamp).padStart(16, '0')}:${current.origin}:${current.id}` : '';
            const accepted = incomingOrder >= currentOrder;
            let committedSequence = 0;
            await new Promise((resolve, reject) => {
                const transaction = db.transaction(['rows', 'changes'], 'readwrite');
                if (accepted) {
                    if (operation.type === 'delete')
                        transaction.objectStore('rows').delete(operation.key);
                    else
                        transaction.objectStore('rows').put(operation.value, operation.key);
                }
                const { sequence: _sequence, ...portable } = operation;
                const change = transaction.objectStore('changes').add(portable);
                change.onsuccess = () => { committedSequence = Number(change.result); };
                transaction.oncomplete = () => resolve();
                transaction.onerror = () => reject(transaction.error);
                transaction.onabort = () => reject(transaction.error);
            });
            this.announceLocalChange(operation.collection, committedSequence);
            this.channel?.postMessage({ collection: operation.collection, sequence: committedSequence });
            if (accepted)
                applied++;
            else
                ignored++;
        }
        return { applied, ignored };
    }
}
